import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused scale computation and FP8 quantization
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/hip/HIPStream.h>

// Kernel to compute max absolute value using reduction
__global__ void compute_amax_kernel(const __half* __restrict__ input, 
                                    float* __restrict__ amax,
                                    int size) {
    __shared__ float shared_max[256];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    float local_max = 0.0f;
    for (int i = idx; i < size; i += stride) {
        float val = fabsf(__half2float(input[i]));
        local_max = fmaxf(local_max, val);
    }

    shared_max[tid] = local_max;
    __syncthreads();

    // Reduction within block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicMax((int*)amax, __float_as_int(shared_max[0]));
    }
}

// Compute scale from amax
torch::Tensor compute_scale_hip(torch::Tensor x, float fp8_max) {
    auto size = x.numel();
    auto amax = torch::zeros({1}, x.options().dtype(torch::kFloat32));

    const int block_size = 256;
    const int num_blocks = min((size + block_size - 1) / block_size, 1024);

    compute_amax_kernel<<<num_blocks, block_size, 0, 
        c10::hip::getCurrentHIPStream()>>>(
        reinterpret_cast<const __half*>(x.data_ptr<at::Half>()),
        amax.data_ptr<float>(),
        size
    );

    // Scale = fp8_max / max(amax, 1e-12)
    auto scale = fp8_max / amax.clamp_min(1e-12f);
    return scale;
}

torch::Tensor quantize_to_fp8_e4m3_hip(torch::Tensor x, torch::Tensor scale, float fp8_max) {
    // Scale and clamp
    auto x_scaled = x * scale;
    auto x_clamped = x_scaled.clamp(-fp8_max, fp8_max);
    return x_clamped.to(torch::kFloat8_e4m3fn);
}
