    fast_quant_dequant_kernel<<<qd_blocks, BLOCK_SIZE, 0, stream>>>(
        reinterpret_cast<const half2*>(x.data_ptr<at::Half>()),
        reinterpret_cast<half2*>(output.data_ptr<at::Half>()),
        scale,
        inv_scale,
