            w_scaled = (self.weight * w_scale).clamp(-self.fp8_max, self.fp8_max)
            w_fp8 = w_scaled.to(self.fp8_dtype)
            self._cached_weight_dequant = w_fp8.to(dtype) / w_scale
            self._weight_version = current_version

